def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(r"\s*(\d+|[A-Z]+[0-9]*|<>|<=|>=|[()+\-*/,:=<>])")
    precedence = {
        "=": 1, "<>": 1, "<": 1, "<=": 1, ">": 1, ">=": 1,
        "+": 2, "-": 2,
        "*": 3, "/": 3,
        "neg": 4,
        ":": 5,
    }

    def parse(formula):
        tokens = token_pattern.findall(formula)
        values = []
        operators = []
        expecting_operand = True
        i = 0

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                values.append(("neg", values.pop()))
            else:
                right = values.pop()
                left = values.pop()
                values.append(("op", op, left, right))

        while i < len(tokens):
            token = tokens[i]

            if token.isdigit():
                values.append(("number", int(token)))
                expecting_operand = False
            elif token in ("SUM", "MIN", "MAX", "IF"):
                operators.append(("(", token, 0))
                i += 1  # Skip the opening parenthesis.
                expecting_operand = True
            elif token[0].isalpha():
                values.append(("cell", token))
                expecting_operand = False
            elif token == "(":
                operators.append(("(", None, 0))
                expecting_operand = True
            elif token == ",":
                while isinstance(operators[-1], str):
                    reduce_operator()
                _, function, commas = operators[-1]
                operators[-1] = ("(", function, commas + 1)
                expecting_operand = True
            elif token == ")":
                while isinstance(operators[-1], str):
                    reduce_operator()
                _, function, commas = operators.pop()
                if function is not None:
                    count = commas + 1
                    args = values[-count:]
                    del values[-count:]
                    values.append(("function", function, args))
                expecting_operand = False
            else:
                op = "neg" if token == "-" and expecting_operand else token
                while (
                    operators
                    and isinstance(operators[-1], str)
                    and (
                        precedence[operators[-1]] > precedence[op]
                        or (
                            precedence[operators[-1]] == precedence[op]
                            and op != "neg"
                        )
                    )
                ):
                    reduce_operator()
                operators.append(op)
                expecting_operand = True
            i += 1

        while operators:
            reduce_operator()
        return values[0]

    parsed = {}
    results = {}
    active = set()

    def is_error(value):
        return isinstance(value, str)

    def evaluate(name):
        tasks = [("cell", name)]
        values = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                cell = task[1]
                if cell not in cells:
                    values.append(0)
                elif cell in results:
                    values.append(results[cell])
                elif cell in active:
                    values.append("#CYCLE!")
                else:
                    active.add(cell)
                    content = cells[cell]
                    tasks.append(("finish_cell", cell))
                    if content.startswith("="):
                        if cell not in parsed:
                            parsed[cell] = parse(content[1:])
                        tasks.append(("eval", parsed[cell]))
                    else:
                        values.append(int(content))

            elif kind == "finish_cell":
                cell = task[1]
                results[cell] = values[-1]
                active.remove(cell)

            elif kind == "eval":
                node = task[1]
                node_kind = node[0]

                if node_kind == "number":
                    values.append(node[1])
                elif node_kind == "cell":
                    tasks.append(("cell", node[1]))
                elif node_kind == "neg":
                    tasks.append(("neg",))
                    tasks.append(("eval", node[1]))
                elif node_kind == "op":
                    tasks.append(("binary_left", node[1], node[3]))
                    tasks.append(("eval", node[2]))
                else:
                    function, args = node[1], node[2]
                    if function == "IF":
                        condition = args[0]
                        tasks.append(("if_left", condition[1], condition[3], args[1], args[2]))
                        tasks.append(("eval", condition[2]))
                    else:
                        expanded = []
                        for arg in args:
                            if arg[0] == "op" and arg[1] == ":":
                                first = arg[2][1]
                                second = arg[3][1]
                                col1, col2 = sorted((ord(first[0]), ord(second[0])))
                                row1, row2 = sorted((int(first[1:]), int(second[1:])))
                                for row in range(row1, row2 + 1):
                                    for col in range(col1, col2 + 1):
                                        cell = chr(col) + str(row)
                                        if cell in cells:
                                            expanded.append(("cell", cell))
                            else:
                                expanded.append(arg)
                        tasks.append(("aggregate", function, expanded, 0, None))

            elif kind == "neg":
                value = values.pop()
                values.append(value if is_error(value) else -value)

            elif kind == "binary_left":
                left = values.pop()
                if is_error(left):
                    values.append(left)
                else:
                    tasks.append(("binary_right", task[1], left))
                    tasks.append(("eval", task[2]))

            elif kind == "binary_right":
                op, left = task[1], task[2]
                right = values.pop()
                if is_error(right):
                    values.append(right)
                elif op == "+":
                    values.append(left + right)
                elif op == "-":
                    values.append(left - right)
                elif op == "*":
                    values.append(left * right)
                elif op == "/":
                    if right == 0:
                        values.append("#DIV/0!")
                    else:
                        quotient = abs(left) // abs(right)
                        values.append(-quotient if (left < 0) != (right < 0) else quotient)

            elif kind == "if_left":
                left = values.pop()
                if is_error(left):
                    values.append(left)
                else:
                    tasks.append(("if_right", task[1], left, task[3], task[4]))
                    tasks.append(("eval", task[2]))

            elif kind == "if_right":
                op, left, then_branch, else_branch = task[1:]
                right = values.pop()
                if is_error(right):
                    values.append(right)
                else:
                    if op == "=":
                        condition = left == right
                    elif op == "<>":
                        condition = left != right
                    elif op == "<":
                        condition = left < right
                    elif op == "<=":
                        condition = left <= right
                    elif op == ">":
                        condition = left > right
                    else:
                        condition = left >= right
                    tasks.append(("eval", then_branch if condition else else_branch))

            elif kind == "aggregate":
                function, args, index, current = task[1:]
                if index == len(args):
                    values.append(0 if current is None else current)
                else:
                    tasks.append(("aggregate_value", function, args, index, current))
                    tasks.append(("eval", args[index]))

            elif kind == "aggregate_value":
                function, args, index, current = task[1:]
                value = values.pop()
                if is_error(value):
                    values.append(value)
                else:
                    if current is None:
                        current = value
                    elif function == "SUM":
                        current += value
                    elif function == "MIN":
                        current = min(current, value)
                    else:
                        current = max(current, value)
                    tasks.append(("aggregate", function, args, index + 1, current))

        return values.pop()

    for name in cells:
        if name not in results:
            evaluate(name)

    return {name: results[name] for name in cells}
